async function NexlabMeasureCommunicationProbe({client,workerBase,projectId=null,fetchImpl=fetch,now=()=>performance.now()}){
  const started=now();
  let sessionMs=0,projectMs=0,requestStarted=null,preparationMs=null,timer=null;
  const elapsed=begin=>Math.max(0,now()-begin);
  const rounded=value=>Math.max(0,Math.round(value));
  const finish=(result,serverTimings=null)=>{
    const total=elapsed(started);
    const requestMs=requestStarted===null?null:elapsed(requestStarted);
    return {...result,latency_ms:requestMs===null?null:rounded(requestMs),request_ms:requestMs===null?null:rounded(requestMs),total_ms:rounded(total),preparation_ms:rounded(preparationMs===null?total:preparationMs),session_ms:rounded(sessionMs),project_ms:rounded(projectMs),server_timings:serverTimings};
  };
  let token=null;
  const sessionStarted=now();
  try{
    const session=await client.auth.getSession();
    if(session?.error)throw session.error;
    token=session?.data?.session?.access_token||null;
  }catch(error){
    sessionMs=elapsed(sessionStarted);
    return finish({state:'warning',worker_ok:null,d1_verified:false,detail:'Sessão indisponível para testar o Worker.',error:String(error?.message||error)});
  }
  sessionMs=elapsed(sessionStarted);
  if(!token)return finish({state:'warning',worker_ok:null,d1_verified:false,detail:'Sessão expirada; comunicação não foi testada.'});
  const controller=new AbortController();
  timer=setTimeout(()=>controller.abort(),8000);
  try{
    if(!projectId){
      const begin=now();
      let selected;
      try{selected=await client.from('projects').select('id').limit(1).abortSignal(controller.signal);}
      finally{projectMs=elapsed(begin);}
      if(selected.error)return finish({state:'warning',worker_ok:null,d1_verified:false,detail:'Não foi possível selecionar um projeto autorizado para testar os comentários.',error:String(selected.error.message||selected.error)});
      projectId=selected.data?.[0]?.id||null;
    }
    if(!projectId)return finish({state:'warning',worker_ok:null,d1_verified:false,detail:'Nenhum projeto disponível para testar a leitura de comentários do D1.'});
    preparationMs=elapsed(started);
    requestStarted=now();
    const response=await fetchImpl(`${workerBase.replace(/\/+$/,'')}/v1/projects/${encodeURIComponent(projectId)}/comments?limit=1`,{method:'GET',headers:{Authorization:`Bearer ${token}`,Accept:'application/json'},cache:'no-store',signal:controller.signal});
    let payload=null;try{payload=await response.json();}catch{}
    const serverTimings={};
    const allowed=new Set(['identity','permissions','authorization','read','worker']);
    for(const part of (response.headers.get('Server-Timing')||'').slice(0,2048).split(',')){
      const match=part.trim().match(/^([a-z_]+);\s*dur=(\d+(?:\.\d+)?)(?:\s*;.*)?$/i);
      if(match&&allowed.has(match[1])&&Number(match[2])<=60000)serverTimings[match[1]]=Number(match[2]);
    }
    const timing=Object.keys(serverTimings).length?serverTimings:null;
    if(response.ok&&Array.isArray(payload?.comments)){
      const slow=elapsed(requestStarted)>3000;
      return finish({state:slow?'warning':'success',worker_ok:true,d1_verified:true,sample_count:payload.comments.length,detail:slow?'Worker e D1 responderam, mas com latência elevada.':'Worker e D1 responderam ao teste de leitura.',http_status:response.status},timing);
    }
    return finish({state:response.status>=500?'danger':'warning',worker_ok:true,d1_verified:false,detail:response.ok?'Worker respondeu, mas o formato dos comentários não foi confirmado.':`Worker respondeu HTTP ${response.status}, mas a leitura do D1 não foi confirmada.`,http_status:response.status,error:String(payload?.error||'')},timing);
  }catch(error){
    const sent=requestStarted!==null;
    return finish({state:sent?'danger':'warning',worker_ok:sent?false:null,d1_verified:false,detail:error?.name==='AbortError'?'O teste de comunicação atingiu o tempo limite.':navigator.onLine===false?'Sem conexão para testar o Worker.':sent?'Não foi possível acessar o Worker de comunicação.':'Não foi possível preparar o teste de comunicação.',error:String(error?.message||error)});
  }finally{clearTimeout(timer);}
}

function NexlabCommunicationTimings({value}){
  if(value?.total_ms==null)return null;
  const lines=[['Preparação do teste',value.preparation_ms],['Requisição completa',value.request_ms],['Total do teste',value.total_ms]];
  const server=value.server_timings;
  if(server){
    lines.push(['Verificação do usuário',server.identity],['Verificação das permissões',server.permissions],['Verificações em paralelo',server.authorization],['Leitura no servidor',server.read],['Total no Worker',server.worker]);
  }
  return o.jsxs('details',{className:'nexlab-communication-timings',children:[
    o.jsx('summary',{children:'Etapas do teste'}),
    o.jsx('dl',{children:lines.filter(([,ms])=>ms!=null).map(([label,ms])=>o.jsxs('div',{children:[o.jsx('dt',{children:label}),o.jsx('dd',{children:`${Math.round(ms)} ms`})]},label))}),
    o.jsx('p',{children:server?'Usuário e permissões são verificados juntos; esses tempos não devem ser somados. A requisição também inclui a rede e a transferência da resposta.':'Os tempos internos serão exibidos quando o Worker atualizado estiver publicado.'})
  ]});
}

